// ΓöÇΓöÇΓöÇ Supported Platforms ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const PLATFORMS = Object.freeze({
  COPILOT: 'copilot',
  CLAUDE: 'claude',
  OPENAI: 'openai',
});

// ΓöÇΓöÇΓöÇ Default Configuration ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const DEFAULT_CONFIG = Object.freeze({
  platform: PLATFORMS.COPILOT,
  timeoutMs: 300000, // 5 minutes default
  maxRetries: 2,
  retryDelayMs: 5000,
  skillsDir: 'templates/sdlc/agents',
  docsDir: 'docs',
});

// ΓöÇΓöÇΓöÇ Invocation Log Entry ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * @typedef {object} InvocationLogEntry
 * @property {string} agentId
 * @property {string} agentName
 * @property {string} platform
 * @property {string} state
 * @property {string} startTime
 * @property {string} [endTime]
 * @property {number} [durationMs]
 * @property {'success'|'failure'|'timeout'|'retry'} status
 * @property {string} [error]
 * @property {number} attempt
 * @property {string} [outputPath]
 */

// ΓöÇΓöÇΓöÇ Dispatcher Class ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

class Dispatcher {
  _store: any;
  _config: any;
  _phaseAgents: any;
  _invoker: (...args: unknown[]) => unknown;
  _onLog: (...args: unknown[]) => void;
  _log: any[];

  /**
   * @param {object} options
   * @param {object} options.store - File store abstraction (read/write/exists)
   * @param {object} [options.config] - Override default config
   * @param {Function} [options.invoker] - Platform invocation function (for testability)
   * @param {Function} [options.onLog] - Callback for invocation log entries
   */
  constructor(options: any = {}) {
    const { store, config = {}, invoker, onLog, phaseAgents } = options;

    if (!store) throw new Error('Dispatcher requires a store');

    this._store = store;
    this._config = { ...DEFAULT_CONFIG, ...config };
    this._phaseAgents = phaseAgents || PHASE_AGENTS;
    this._invoker = invoker || this._defaultInvoker.bind(this);
    this._onLog = onLog || (() => {});
    this._log = [];
  }

  /** @returns {InvocationLogEntry[]} Full invocation log */
  get log() {
    return [...this._log];
  }

  /**
   * Get the agents assigned to a given state.
   * @param {string} state
   * @returns {Array<{id: string, name: string}>}
   */
  getAgentsForState(state: string) {
    return this._phaseAgents[state] || [];
  }

  /**
   * Build agent invocation context.
   * AC-3: Reads predecessor output files and injects as context.
   * AC-4: Loads questionnaire answers.
   *
   * @param {string} agentId
   * @param {object} options
   * @param {string[]} [options.predecessorPaths] - Paths to predecessor outputs
   * @param {string} [options.questionnairePath] - Path to questionnaire answers
   * @param {object} [options.sessionState] - Current session state
   * @returns {object} Assembled context object
   */
  buildContext(agentId: string, options: any = {}) {
    const { predecessorPaths = [], questionnairePath, sessionState } = options;
    const context = {
      agentId,
      skillFile: path.join(this._config.skillsDir, `${agentId}-*.md`),
      predecessorOutputs: {},
      questionnaireInput: null,
      sessionState: sessionState || null,
    };

    // AC-3: Load predecessor outputs
    for (const p of predecessorPaths) {
      if (this._store.exists(p)) {
        context.predecessorOutputs[p] = this._store.read(p);
      }
    }

    // AC-4: Load questionnaire answers
    if (questionnairePath && this._store.exists(questionnairePath)) {
      context.questionnaireInput = this._store.read(questionnairePath);
    }

    return context;
  }

  /**
   * Invoke a single agent with retry and timeout handling.
   * AC-1, AC-2, AC-5, AC-6, AC-7, AC-8
   *
   * @param {object} agent - { id, name }
   * @param {string} state - Current state
   * @param {object} context - Built context from buildContext()
   * @param {object} [agentConfig] - Per-agent config overrides
   * @returns {Promise<{success: boolean, outputPath?: string, error?: string}>}
   */
  async invoke(agent: any, state: string, context: any, agentConfig: any = {}) {
    const config = { ...this._config, ...agentConfig };
    const platform = agentConfig.platform || config.platform;
    let lastError = null;

    for (let attempt = 1; attempt <= config.maxRetries + 1; attempt++) {
      const entry: any = {
        agentId: agent.id,
        agentName: agent.name,
        platform,
        state,
        startTime: new Date().toISOString(),
        status: 'success',
        attempt,
      };

      try {
        const result = await this._withTimeout(
          this._invoker(agent, platform, context),
          config.timeoutMs
        );

        entry.endTime = new Date().toISOString();
        entry.durationMs = +new Date(entry.endTime) - +new Date(entry.startTime);
        entry.outputPath = result.outputPath;
        entry.status = 'success';

        this._logEntry(entry);
        return { success: true, outputPath: result.outputPath };
      } catch (err) {
        lastError = err;
        entry.endTime = new Date().toISOString();
        entry.durationMs = +new Date(entry.endTime) - +new Date(entry.startTime);
        entry.error = err.message;
        entry.status = Dispatcher._classifyError(err, attempt, config.maxRetries);

        this._logEntry(entry);

        if (attempt <= config.maxRetries) {
          await this._delay(config.retryDelayMs);
        }
      }
    }

    return {
      success: false,
      error: lastError ? lastError.message : 'Unknown error',
    };
  }

  /**
   * Dispatch all agents for a given state sequentially.
   * @param {string} state
   * @param {object} contextOptions - Options for buildContext
   * @param {object} [agentConfigs] - Map of agentId ΓåÆ config overrides
   * @param {object} [dispatchOptions] - { onFailure: 'continue'|'abort'|'escalate' }
   * @returns {Promise<{completed: string[], failed: string[], results: object[], escalated: boolean}>}
   */
  async dispatchState(
    state: string,
    contextOptions: any = {},
    agentConfigs: any = {},
    dispatchOptions: any = {}
  ) {
    const { onFailure = 'continue' } = dispatchOptions;
    const agents = this.getAgentsForState(state);
    const completed = [];
    const failed = [];
    const results = [];
    let escalated = false;

    for (const agent of agents) {
      const context = this.buildContext(agent.id, contextOptions);
      const agentConfig = agentConfigs[agent.id] || {};
      const result = await this.invoke(agent, state, context, agentConfig);

      results.push({ agent, ...result });

      if (result.success) {
        completed.push(agent.id);
        // Add output to contextOptions.predecessorPaths for next agent
        if (result.outputPath) {
          contextOptions.predecessorPaths = contextOptions.predecessorPaths || [];
          contextOptions.predecessorPaths.push(result.outputPath);
        }
      } else {
        failed.push(agent.id);
        if (onFailure === 'abort') {
          break;
        }
        if (onFailure === 'escalate') {
          escalated = true;
          break;
        }
      }
    }

    return { completed, failed, results, escalated };
  }

  // ΓöÇΓöÇΓöÇ Internal ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  static _classifyError(err: any, attempt: number, maxRetries: number) {
    if (err.message === 'TIMEOUT') return 'timeout';
    return attempt <= maxRetries ? 'retry' : 'failure';
  }

  /** @private ΓÇö Default invoker (no-op for testing) */
  async _defaultInvoker(_agent: any, _platform: string, _context: any) {
    throw new Error('No invoker configured. Provide an invoker function.');
  }

  /** @private ΓÇö Promise with timeout */
  _withTimeout(promise: Promise<any>, ms: number) {
    if (ms <= 0) return promise;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => reject(new Error('TIMEOUT')), ms);
      promise
        .then((val) => {
          clearTimeout(timer);
          resolve(val);
        })
        .catch((err) => {
          clearTimeout(timer);
          reject(err);
        });
    });
  }

  /** @private */
  _delay(ms: number) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /** @private */
  _logEntry(entry: any) {
    this._log.push(entry);
    this._onLog(entry);
  }
}

export { PHASE_AGENTS, PLATFORMS, DEFAULT_CONFIG, Dispatcher };

/**
 * Orchestrator Engine ΓÇö Integrates state machine, flow loader,
 * persistence, and SSE events (FEAT-05-A / AC-1, AC-6, AC-7)
 *
 * This is the top-level entry point for the orchestrator subsystem.
 * It wires together:
 *   - flow-loader.js (reads flows.yaml)
 *   - state-machine.js (drives transitions)
 *   - state-persistence.js (reads/writes session-state.json)
 *   - SSE notifications (pushes events to connected UI clients)
 *
 * @module orchestrator/engine
 */

import { loadFlows } from './flow-loader';
import {
  STATES as _STATES,
  EVENTS as _EVENTS,
  StateMachine,
  buildTransitionMap as _buildTransitionMap,
  createStateMachine,
  createCombinationMachine as _createCombinationMachine,
  createHotfixMachine as _createHotfixMachine,
} from './state-machine';
import {
  loadSessionState,
  saveSessionState,
  createAutoPersist,
  saveRunHistory,
  loadRunHistory,
} from './state-persistence';
import { runGate } from './gate-validator';
import { runSprintGate } from './sprint-gate';
import { loadTemplate } from './template-loader';

/**
 * @typedef {object} EngineOptions
 * @property {object} store - File store abstraction (read/write/exists/mkdirp)
 * @property {Function} [sseNotify] - SSE broadcast function (eventType, data)
 * @property {string} [flowsPath] - Override path to flows.yaml
 * @property {string} [sessionPath] - Override path to session-state.json
 * @property {string} [templateName] - Template to load (default: 'sdlc')
 * @property {string} [templatesDir] - Override templates base directory
 */

/**
 * Create and initialize the orchestrator engine.
 *
 * 1. Loads template manifest and resolves template paths
 * 2. Loads flows.yaml (AC-1)
 * 3. Loads persisted session state for crash recovery (AC-7)
 * 4. Creates a StateMachine with auto-persist and SSE wiring (AC-6)
 *
 * @param {EngineOptions} options
 * @returns {{ machine: StateMachine, flows: object, template: object, advance: Function, error: Function, recover: Function, status: Function }}
 */
function createEngine(options: any) {
  const { store, sseNotify, flowsPath, sessionPath, templateName, templatesDir } = options;

  if (!store) throw new Error('Engine requires a store');

  // Load template manifest (defaults to 'sdlc')
  let template = null;
  try {
    template = loadTemplate(templateName, templatesDir);
  } catch (_err) {
    // Template loading is optional ΓÇö fall back to hardcoded defaults
    template = null;
  }

  // AC-1: Load declarative flow definition
  const flows = loadFlows(store, flowsPath);

  // AC-7: Load persisted state for crash recovery
  const sessionState = loadSessionState(store, sessionPath);

  // Determine mode from persisted state or default to CREATE
  const mode = (sessionState && sessionState.mode) || 'CREATE';

  // Variable to hold the machine reference for autopersist closure
  let machine = null;

  // SSE bridge: forward state machine events to connected UI clients
  const sseForward = sseNotify || (() => {});
  const onTransition = (event) => {
    sseForward('orchestrator:transition', event);
  };
  const onError = (event) => {
    sseForward('orchestrator:error', event);
  };

  // Auto-persist: save to session-state.json on every transition/error
  const autoPersist = createAutoPersist(
    store,
    () => machine,
    sessionPath,
    (serialized) => {
      sseForward('orchestrator:state_saved', {
        status: serialized.status,
        last_updated: serialized.last_updated,
      });
    }
  );

  // Combined callbacks: SSE + auto-persist
  const combinedOnTransition = (event) => {
    onTransition(event);
    autoPersist.onTransition(event);
  };
  const combinedOnError = (event) => {
    onError(event);
    autoPersist.onError(event);
  };

  // Create the state machine (crash recovery is handled by constructor)
  const smOptions: any = {
    onTransition: combinedOnTransition,
    onError: combinedOnError,
  };
  if (template && template.modes) {
    smOptions.modeConfigs = template.modes;
  }
  machine = createStateMachine(mode, sessionState, smOptions);

  // ΓöÇΓöÇ Public API ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  /**
   * Advance the state machine to the next state.
   * @param {object} [gateResult] - Gate validation result for critic states
   * @returns {{ from: string, to: string, timestamp: string }}
   */
  function advance(gateResult?: any) {
    return machine.advance(gateResult);
  }

  /**
   * Force the machine into ERROR state.
   * @param {string} reason
   */
  function error(reason: string) {
    machine.error(reason);
  }

  /**
   * Recover from ERROR state.
   * @returns {string} The state recovered to
   */
  function recover() {
    return machine.recover();
  }

  /**
   * Get current engine status.
   * @returns {object}
   */
  function status() {
    return {
      state: machine.state,
      mode: machine.mode,
      nextState: machine.nextState,
      history: machine.history,
      elapsedMs: machine.elapsedMs,
      phaseMetadata: machine.stateMetadata(),
      serialized: machine.serialize(),
      templateName: template ? template.name : null,
    };
  }

  /**
   * Stop the running pipeline. Sets the machine to ERROR with a USER_STOPPED reason.
   * @returns {object} Updated engine status
   */
  function stop() {
    archiveCurrentRun('STOPPED');
    machine.error('USER_STOPPED');
    sseForward('orchestrator:stopped', { state: machine.state, mode: machine.mode });
    return status();
  }

  /** Archive the current run into run-history.json (if non-trivial). */
  function archiveCurrentRun(endStatus: string) {
    if (machine.history.length === 0) return; // nothing to archive
    const serialized = machine.serialize();
    saveRunHistory(
      store,
      {
        mode: serialized.mode,
        status: endStatus,
        started_at: serialized.started_at || serialized.last_updated,
        ended_at: new Date().toISOString(),
        state_history: serialized.state_history,
        gate_results: serialized.gate_results,
      },
      sessionPath ? sessionPath.replace(/session-state\.json$/, 'run-history.json') : undefined
    );
  }

  /**
   * Reset the engine with a new mode.
   * Creates a fresh state machine and persists the new state.
   *
   * @param {string} newMode - Command mode
   * @param {string[]} [phases] - Override phases for combination runs
   * @returns {object} New engine status
   */
  function reset(newMode: string, phases?: string[]) {
    archiveCurrentRun('RESET');
    const smOpts: any = {
      mode: newMode,
      onTransition: combinedOnTransition,
      onError: combinedOnError,
    };
    if (template && template.modes) {
      smOpts.modeConfigs = template.modes;
    }
    if (phases && phases.length > 0) {
      smOpts.phases = phases;
      machine = new StateMachine(smOpts);
    } else {
      machine = createStateMachine(newMode, null, smOpts);
    }

    // Persist the fresh state
    saveSessionState(store, machine.serialize(), sessionPath);
    sseForward('orchestrator:reset', { mode: newMode, state: machine.state });

    return status();
  }

  /**
   * Run gate validation for the current critic state (FEAT-05-C).
   * Validates deliverables against contracts and guardrails,
   * emits SSE events, and returns a structured result.
   *
   * @param {string[]} deliverables - Paths to deliverable files to validate
   * @param {object} [opts] - Override contractsDir / guardrailsDir
   * @returns {{verdict: string, violations: Array, questionnaireRequests: Array, summary: object}}
   */
  function validateGate(deliverables: string[], opts: any = {}) {
    const criticState = machine.state;
    const gateOpts: any = { criticState, deliverables, ...opts };
    if (template) {
      if (!opts.contractsDir && template.contractsDir) {
        gateOpts.contractsDir = template.contractsDir;
      }
      if (!opts.guardrailsDir && template.guardrailsDir) {
        gateOpts.guardrailsDir = template.guardrailsDir;
      }
      if (!opts.criticToPhase && template.criticToPhase) {
        gateOpts.criticToPhase = template.criticToPhase;
      }
      if (!opts.phaseContracts && template.phaseContracts) {
        gateOpts.phaseContracts = template.phaseContracts;
      }
      if (!opts.phaseGuardrails && template.phaseGuardrails) {
        gateOpts.phaseGuardrails = template.phaseGuardrails;
      }
    }
    const result: any = runGate(store, gateOpts);

    // AC-7: Emit SSE events for gate results
    if (result.verdict === 'APPROVED') {
      sseForward('orchestrator:gate_passed', {
        criticState,
        phase: result.summary.phase,
        deliverableCount: result.summary.deliverableCount,
        timestamp: result.summary.timestamp,
      });
    } else {
      sseForward('orchestrator:gate_failed', {
        criticState,
        phase: result.summary.phase,
        violationCount: result.summary.totalViolations,
        bySeverity: result.summary.bySeverity,
        questionnaireRequestCount: result.summary.questionnaireRequestCount,
        timestamp: result.summary.timestamp,
      });
    }

    return result;
  }

  /**
   * Run the Sprint Gate readiness check (FEAT-05-D).
   * Validates Definition of Ready, loads decisions, injects lessons-learned,
   * checks velocity capacity, and scans for open blockers.
   *
   * @param {object} opts
   * @param {string} opts.sprintId - e.g. 'SP-5'
   * @param {Array<object>} opts.stories - Sprint backlog items
   * @param {number} [opts.plannedItems] - Override planned item count
   * @param {object} [opts.paths] - Override file paths
   * @returns {{verdict: string, blockers: Array, steps: object, summary: object}}
   */
  function sprintGate(opts: any = {}) {
    if (template && template.decisionCategories && !opts.templateConfig) {
      opts = { ...opts, templateConfig: { decisionCategories: template.decisionCategories } };
    }
    const result: any = runSprintGate(store, opts);

    if (result.verdict === 'READY') {
      sseForward('orchestrator:sprint_gate_ready', {
        sprintId: result.summary.sprintId,
        storyCount: result.summary.storyCount,
        lessonsInjected: result.summary.lessonsInjected,
        velocityRatio: result.summary.velocityRatio,
        timestamp: result.summary.timestamp,
      });
    } else {
      sseForward('orchestrator:sprint_gate_blocked', {
        sprintId: result.summary.sprintId,
        blockerCount: result.summary.totalBlockers,
        openBlockerCount: result.summary.openBlockerCount,
        timestamp: result.summary.timestamp,
      });
    }

    return result;
  }

  /**
   * Load historical run records.
   * @returns {Array<object>}
   */
  function runHistory() {
    return loadRunHistory(
      store,
      sessionPath ? sessionPath.replace(/session-state\.json$/, 'run-history.json') : undefined
    );
  }

  return {
    machine,
    flows,
    template,
    advance,
    error,
    recover,
    status,
    stop,
    reset,
    validateGate,
    sprintGate,
    runHistory,
  };
}

export { createEngine };

/**
 * Flow Loader ΓÇö Minimal YAML-subset parser for flows.yaml (FEAT-05-A / AC-1)
 *
 * Zero external dependencies. Parses the simple structure used in flows.yaml:
 *   - Top-level keys (no nesting beyond mode config)
 *   - Arrays of strings (prefixed with "  - ")
 *   - Nested maps (modes ΓåÆ { phases: [], label: string })
 *
 * @module orchestrator/flow-loader
 */

import path from 'path';

// ΓöÇΓöÇΓöÇ Minimal YAML Parser ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Parse the flows.yaml subset into a JS object.
 * Handles: comments (#), top-level keys, arrays (- item),
 * nested maps (two-level), inline strings, and inline arrays ([]).
 *
 * @param {string} content - Raw YAML content
 * @returns {object} Parsed flow definition
 */
function parseFlowYaml(content: string) {
  const result: any = {};
  let currentKey = null;
  let currentMode = null;
  let modeKey = null;

  const lines = content.split('\n');

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    const stripped = raw.replace(/#.*$/, '').trimEnd();

    if (stripped.length === 0) continue;

    const indent = raw.search(/\S/);

    // Top-level key (indent 0, ends with ':')
    if (indent === 0 && stripped.endsWith(':')) {
      currentKey = stripped.slice(0, -1).trim();
      currentMode = null;
      modeKey = null;
      if (!result[currentKey]) result[currentKey] = null;
      continue;
    }

    // Top-level key with inline value (indent 0, contains ':')
    if (indent === 0 && stripped.includes(':')) {
      const colonIdx = stripped.indexOf(':');
      const key = stripped.slice(0, colonIdx).trim();
      const val = stripped.slice(colonIdx + 1).trim();
      result[key] = parseInlineValue(val);
      currentKey = null;
      currentMode = null;
      continue;
    }

    if (currentKey === null) continue;

    // Mode-level nested map entry (indent 2, ends with ':')
    if (indent === 2 && stripped.trimStart().endsWith(':')) {
      const name = stripped.trimStart().slice(0, -1);
      if (currentKey === 'modes') {
        if (!result.modes) result.modes = {};
        result.modes[name] = {};
        currentMode = name;
        modeKey = null;
      }
      continue;
    }

    // Mode property (indent 4, has ':')
    if (indent === 4 && currentMode && stripped.includes(':')) {
      const colonIdx = stripped.trimStart().indexOf(':');
      const propName = stripped.trimStart().slice(0, colonIdx).trim();
      const propVal = stripped
        .trimStart()
        .slice(colonIdx + 1)
        .trim();

      if (propVal.length > 0 && propVal !== '') {
        result.modes[currentMode][propName] = parseInlineValue(propVal);
        modeKey = null;
      } else {
        // Property without inline value (array follows)
        modeKey = propName;
        result.modes[currentMode][propName] = [];
      }
      continue;
    }

    // Array item under mode property (indent 6, starts with "- ")
    if (indent === 6 && currentMode && modeKey && stripped.trimStart().startsWith('- ')) {
      const item = stripped.trimStart().slice(2).trim();
      result.modes[currentMode][modeKey].push(item);
      continue;
    }

    // Top-level array item (indent 2, starts with "- ")
    if (indent === 2 && stripped.trimStart().startsWith('- ')) {
      if (!Array.isArray(result[currentKey])) result[currentKey] = [];
      const item = stripped.trimStart().slice(2).trim();
      result[currentKey].push(item);
      continue;
    }
  }

  return result;
}

/**
 * Parse an inline YAML value.
 * Handles: inline arrays [a, b], quoted strings, plain strings.
 */
function parseInlineValue(val: string) {
  if (val.startsWith('[') && val.endsWith(']')) {
    const inner = val.slice(1, -1).trim();
    if (inner.length === 0) return [];
    return inner.split(',').map((s) => s.trim());
  }
  // Quoted string
  if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
    return val.slice(1, -1);
  }
  return val;
}

// ΓöÇΓöÇΓöÇ Flow Loader ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Load and validate flows.yaml.
 * @param {object} store - Store abstraction (read/exists)
 * @param {string} [flowsPath] - Override path to flows.yaml
 * @returns {object} Validated flow definition { states, full_flow, structural_states, modes, events }
 * @throws {Error} If file is missing or validation fails
 */
function loadFlows(store: any, flowsPath?: string) {
  const filePath = flowsPath || path.join(__dirname, 'flows.yaml');

  if (!store.exists(filePath)) {
    throw new Error(`Flow definition not found: ${filePath}`);
  }

  const content = store.readFile(filePath);
  const parsed = parseFlowYaml(content);

  // Validate required sections
  const required = ['states', 'full_flow', 'structural_states', 'modes', 'events'];
  for (const key of required) {
    if (!parsed[key]) {
      throw new Error(`flows.yaml missing required section: ${key}`);
    }
  }

  // Validate that full_flow entries are in states
  const stateSet = new Set(parsed.states);
  for (const s of parsed.full_flow) {
    if (!stateSet.has(s)) {
      throw new Error(`full_flow references unknown state: ${s}`);
    }
  }

  // Validate mode phases reference real states
  for (const [modeName, modeConfig] of Object.entries(parsed.modes) as [string, any][]) {
    if (!modeConfig.phases) {
      throw new Error(`Mode "${modeName}" missing phases property`);
    }
    if (!modeConfig.label) {
      throw new Error(`Mode "${modeName}" missing label property`);
    }
  }

  return {
    states: parsed.states,
    full_flow: parsed.full_flow,
    structural_states: parsed.structural_states,
    modes: parsed.modes,
    events: parsed.events,
  };
}

export { parseFlowYaml, parseInlineValue, loadFlows };

/**
 * Flow Schema Validator ΓÇö Validates flows.json against flow-canonical.schema.json (FEAT-03 / S4-2)
 *
 * @module orchestrator/flow-schema
 */

import fs from 'node:fs';
import path from 'node:path';
import Ajv2020 from 'ajv/dist/2020';
import addFormats from 'ajv-formats';

const SCHEMA_PATH = path.resolve(__dirname, '..', 'schema', 'flow-canonical.schema.json');
const FLOWS_PATH = path.resolve(__dirname, '..', 'schema', 'flows.json');

function readJson(filePath: string): any {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

/**
 * Validate flows.json against the canonical flow schema.
 * @param {object} [options]
 * @param {string} [options.schemaPath] - Override schema path
 * @param {string} [options.flowsPath] - Override flows data path
 * @returns {{ valid: boolean, errors: object[], flowsPath: string, stateCount: number, modeCount: number, gateCount: number }}
 */
function validateCanonicalFlows(options: any = {}) {
  const schemaPath = options.schemaPath || SCHEMA_PATH;
  const flowsPath = options.flowsPath || FLOWS_PATH;

  const schema = readJson(schemaPath);
  const data: any = readJson(flowsPath);

  const ajv = new Ajv2020({ allErrors: true, strict: false });
  addFormats(ajv);
  const validate = ajv.compile(schema);
  const valid = validate(data);

  // Semantic checks: fullFlow states must exist in states
  const semanticErrors = [];
  const d: any = data;
  if (valid && Array.isArray(d.states) && Array.isArray(d.fullFlow)) {
    const stateSet = new Set(d.states);
    for (const s of d.fullFlow) {
      if (!stateSet.has(s)) {
        semanticErrors.push({ message: `fullFlow references unknown state: ${s}` });
      }
    }
    for (const s of d.structuralStates || []) {
      if (!stateSet.has(s)) {
        semanticErrors.push({ message: `structuralStates references unknown state: ${s}` });
      }
    }
    // Gate references must exist
    for (const gate of d.gates || []) {
      if (!stateSet.has(gate.after)) {
        semanticErrors.push({
          message: `gate ${gate.id} references unknown after state: ${gate.after}`,
        });
      }
      if (!stateSet.has(gate.before)) {
        semanticErrors.push({
          message: `gate ${gate.id} references unknown before state: ${gate.before}`,
        });
      }
    }
    // Mode phases must be valid states
    for (const [modeName, modeDef] of Object.entries(d.modes || {})) {
      for (const phase of (modeDef as any).phases || []) {
        if (!stateSet.has(phase)) {
          semanticErrors.push({ message: `mode ${modeName} references unknown phase: ${phase}` });
        }
      }
    }
  }

  return {
    valid: valid && semanticErrors.length === 0,
    errors: [...(validate.errors || []), ...semanticErrors],
    flowsPath,
    stateCount: Array.isArray(data.states) ? data.states.length : 0,
    modeCount: data.modes ? Object.keys(data.modes).length : 0,
    gateCount: Array.isArray(data.gates) ? data.gates.length : 0,
  };
}

export { SCHEMA_PATH, FLOWS_PATH, validateCanonicalFlows };

/**
 * Gate Validator ΓÇö Critic + Risk validation engine (FEAT-05-C)
 *
 * Validates agent deliverables against contracts and guardrails
 * before allowing state transitions through critic gates.
 *
 * Checks:
 *   - Contract compliance: required sections present, not empty/placeholder
 *   - Anti-hallucination: UNCERTAIN: and INSUFFICIENT_DATA: properly documented
 *   - Guardrail compliance: rules loaded and violations tracked
 *   - Handoff checklist: all 9 items present and checked
 *   - Questionnaire extraction: QUESTIONNAIRE_REQUEST items collected
 *
 * @module orchestrator/gate-validator
 */

import path from 'path';

// ΓöÇΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const CONTRACTS_DIR = 'templates/sdlc/contracts';
const GUARDRAILS_DIR = 'templates/sdlc/guardrails';

/** Maps CRITIC states to the phase they validate */
const CRITIC_TO_PHASE = {
  CRITIC_1: 'PHASE_1',
  CRITIC_2: 'PHASE_2',
  CRITIC_3: 'PHASE_3',
  CRITIC_4: 'PHASE_4',
};

/** Maps phases to applicable guardrail files */
const PHASE_GUARDRAILS = {
  PHASE_1: ['00-global-guardrails.md', '01-business-guardrails.md'],
  PHASE_2: [
    '00-global-guardrails.md',
    '02-architecture-guardrails.md',
    '03-security-guardrails.md',
  ],
  PHASE_3: ['00-global-guardrails.md', '04-ux-guardrails.md', '08-content-guardrails.md'],
  PHASE_4: ['00-global-guardrails.md', '05-marketing-guardrails.md'],
};

/** Maps phases to applicable contract files */
const PHASE_CONTRACTS = {
  PHASE_1: [
    'analysis-output-contract.md',
    'recommendations-output-contract.md',
    'sprintplan-output-contract.md',
    'guardrails-output-contract.md',
  ],
  PHASE_2: [
    'analysis-output-contract.md',
    'recommendations-output-contract.md',
    'sprintplan-output-contract.md',
    'guardrails-output-contract.md',
  ],
  PHASE_3: [
    'analysis-output-contract.md',
    'recommendations-output-contract.md',
    'sprintplan-output-contract.md',
    'guardrails-output-contract.md',
  ],
  PHASE_4: [
    'analysis-output-contract.md',
    'recommendations-output-contract.md',
    'sprintplan-output-contract.md',
    'guardrails-output-contract.md',
  ],
};

/** Placeholder patterns banned by G-GLOB-17 */
const PLACEHOLDER_PATTERNS = [
  /\[TODO\]/i,
  /\[FILL\s+IN/i,
  /\[SEE\s+BELOW\]/i,
  /\[TBD\]/i,
  /\[PLACEHOLDER\]/i,
  /\[INSERT\s/i,
];

/** Tags tracked during validation */
const TRACKED_TAGS = [
  'UNCERTAIN:',
  'INSUFFICIENT_DATA:',
  'QUESTIONNAIRE_REQUEST',
  'GUARDRAIL_VIOLATION:',
  'SECURITY_FLAG:',
  'OUT_OF_SCOPE:',
];

/** Minimum number of canonical handoff checklist items (G-GLOB-20) */
const HANDOFF_CHECKLIST_COUNT = 9;

// ΓöÇΓöÇΓöÇ Parsing Functions ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Extract markdown heading sections from content.
 * @param {string} markdown
 * @returns {Array<{level: number, title: string, content: string}>}
 */
function extractSections(markdown: string) {
  const lines = markdown.split('\n');
  const sections = [];
  let current = null;

  for (const line of lines) {
    const match = line.match(/^(#{1,6})\s+(.+)$/);
    if (match) {
      if (current) {
        current.content = current.content.trim();
        sections.push(current);
      }
      current = { level: match[1].length, title: match[2].trim(), content: '' };
    } else if (current) {
      current.content += line + '\n';
    }
  }
  if (current) {
    current.content = current.content.trim();
    sections.push(current);
  }
  return sections;
}

/**
 * Find placeholder text patterns in content (G-GLOB-17).
 * @param {string} content
 * @returns {Array<{line: number, text: string, pattern: string}>}
 */
function findPlaceholders(content: string) {
  const found = [];
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    for (const pattern of PLACEHOLDER_PATTERNS) {
      if (pattern.test(lines[i])) {
        found.push({ line: i + 1, text: lines[i].trim(), pattern: pattern.source });
        break;
      }
    }
  }
  return found;
}

/**
 * Extract items with a specific tag prefix from content.
 * @param {string} content
 * @param {string} tag - e.g. 'UNCERTAIN:', 'INSUFFICIENT_DATA:'
 * @returns {Array<{line: number, tag: string, text: string, fullLine: string}>}
 */
function extractTaggedItems(content: string, tag: string) {
  const items = [];
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const idx = lines[i].indexOf(tag);
    if (idx >= 0) {
      items.push({
        line: i + 1,
        tag,
        text: lines[i].substring(idx + tag.length).trim(),
        fullLine: lines[i].trim(),
      });
    }
  }
  return items;
}

/**
 * Parse the handoff checklist from a markdown document.
 * Looks for `## HANDOFF CHECKLIST` heading and counts checked/unchecked items.
 * @param {string} content
 * @returns {{found: boolean, checked: number, unchecked: number, total: number, items: Array}}
 */
function parseHandoffChecklist(content: string) {
  const checklistMatch = content.match(/##\s*HANDOFF\s+CHECKLIST/i);
  if (!checklistMatch) {
    return { found: false, checked: 0, unchecked: 0, total: 0, items: [] };
  }

  const afterChecklist = content.substring(checklistMatch.index + checklistMatch[0].length);

  // Bound by next same-or-higher-level heading
  const nextHeading = afterChecklist.match(/\n#{1,2}\s+(?!#)/);
  const checklistContent = nextHeading
    ? afterChecklist.substring(0, nextHeading.index)
    : afterChecklist;

  const items = [];
  const lines = checklistContent.split('\n');
  for (const line of lines) {
    const checkedMatch = line.match(/^\s*-\s*\[x\]\s*(.+)/i);
    const uncheckedMatch = line.match(/^\s*-\s*\[\s*\]\s*(.+)/);
    if (checkedMatch) items.push({ text: checkedMatch[1].trim(), checked: true });
    else if (uncheckedMatch) items.push({ text: uncheckedMatch[1].trim(), checked: false });
  }

  return {
    found: true,
    checked: items.filter((i) => i.checked).length,
    unchecked: items.filter((i) => !i.checked).length,
    total: items.length,
    items,
  };
}

/**
 * Load required section titles from a contract markdown file.
 * Extracts headings under "MANDATORY SECTIONS" or "MANDATORY SCHEMA".
 * @param {object} store
 * @param {string} contractPath
 * @returns {string[]} List of required section titles
 */
function loadContractSections(store: any, contractPath: string) {
  if (!store.exists(contractPath)) return [];
  const content = store.readFile(contractPath);
  const sections = [];

  const mandatoryMatch = content.match(/##\s*MANDATORY\s+(SECTIONS|SCHEMA)/i);
  if (!mandatoryMatch) return [];

  const afterMandatory = content.substring(mandatoryMatch.index);
  const lines = afterMandatory.split('\n');

  for (let i = 1; i < lines.length; i++) {
    // Stop at a new top-level section that isn't part of mandatory
    if (/^##\s+[^#]/.test(lines[i]) && !/MANDATORY/i.test(lines[i])) break;
    const heading = lines[i].match(/^###\s+\d+\.\s+(.+)/);
    if (heading) sections.push(heading[1].trim());
  }
  return sections;
}

/**
 * Load guardrail rule IDs from a guardrail file.
 * @param {object} store
 * @param {string} guardrailPath
 * @returns {string[]} List of rule IDs (e.g. 'G-GLOB-01')
 */
function loadGuardrailRules(store: any, guardrailPath: string) {
  if (!store.exists(guardrailPath)) return [];
  const content = store.readFile(guardrailPath);
  const rules = new Set();
  // Pattern 1: heading format ΓÇö ### G-XXX-NN
  for (const m of content.matchAll(/###\s+(G-[A-Z]+-\d+)/g)) {
    rules.add(m[1]);
  }
  // Pattern 2: table row format ΓÇö | G-XXX-NN |
  for (const m of content.matchAll(/\|\s*(G-[A-Z]+-\d+)\s*\|/g)) {
    rules.add(m[1]);
  }
  return [...rules];
}

// ΓöÇΓöÇΓöÇ Document Validation ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Validate a single deliverable document against quality checks.
 *
 * @param {string} content - Markdown content of the deliverable
 * @param {object} [options]
 * @param {string[]} [options.requiredSections] - Contract section titles to verify
 * @returns {{violations: Array, tags: object, handoff: object}}
 */
function validateDocument(content: string, options: any = {}) {
  const violations = [];
  const { requiredSections = [] } = options;

  if (!content || !content.trim()) {
    violations.push({
      severity: 'CRITICAL',
      rule: 'EMPTY_DELIVERABLE',
      description: 'Deliverable is empty or contains only whitespace',
    });
    return {
      violations,
      tags: {},
      handoff: { found: false, checked: 0, unchecked: 0, total: 0, items: [] },
    };
  }

  // AC-2: Check required sections (not empty, not placeholder)
  const sections = extractSections(content);
  if (requiredSections.length > 0) {
    const sectionTitles = sections.map((s) => s.title.toLowerCase());
    for (const required of requiredSections) {
      const found = sectionTitles.some((t) => t.includes(required.toLowerCase()));
      if (!found) {
        violations.push({
          severity: 'MAJOR',
          rule: 'MISSING_SECTION',
          description: `Required section missing: "${required}"`,
        });
      }
    }
  }

  // Check for empty sections
  for (const section of sections) {
    if (!section.content.trim()) {
      violations.push({
        severity: 'MAJOR',
        rule: 'EMPTY_SECTION',
        description: `Section "${section.title}" is empty`,
      });
    }
  }

  // AC-2: Check placeholder text (G-GLOB-17)
  const placeholders = findPlaceholders(content);
  for (const ph of placeholders) {
    violations.push({
      severity: 'MAJOR',
      rule: 'PLACEHOLDER_TEXT',
      description: `Placeholder text at line ${ph.line}: "${ph.text}"`,
    });
  }

  // AC-3: Extract tagged items
  const tags = {};
  for (const tag of TRACKED_TAGS) {
    tags[tag] = extractTaggedItems(content, tag);
  }

  // Explicit GUARDRAIL_VIOLATION tags in the deliverable are findings
  for (const gv of tags['GUARDRAIL_VIOLATION:'] || []) {
    violations.push({
      severity: 'MAJOR',
      rule: 'GUARDRAIL_VIOLATION',
      description: `Guardrail violation documented: ${gv.text}`,
      line: gv.line,
    });
  }

  // AC-5: Parse and verify handoff checklist
  const handoff = parseHandoffChecklist(content);
  if (!handoff.found) {
    violations.push({
      severity: 'CRITICAL',
      rule: 'MISSING_HANDOFF_CHECKLIST',
      description: 'Handoff checklist section not found (G-GLOB-20)',
    });
  } else {
    if (handoff.unchecked > 0) {
      violations.push({
        severity: 'CRITICAL',
        rule: 'INCOMPLETE_HANDOFF',
        description: `Handoff checklist has ${handoff.unchecked} unchecked item(s) out of ${handoff.total} (G-GLOB-21)`,
      });
    }
    if (handoff.total < HANDOFF_CHECKLIST_COUNT) {
      violations.push({
        severity: 'MAJOR',
        rule: 'INSUFFICIENT_HANDOFF_ITEMS',
        description: `Handoff checklist has ${handoff.total} items, expected at least ${HANDOFF_CHECKLIST_COUNT} (G-GLOB-20)`,
      });
    }
  }

  return { violations, tags, handoff };
}

// ΓöÇΓöÇΓöÇ Gate Runner ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Run the full gate validation for a critic state.
 *
 * AC-1: Reads contract definitions from contracts directory
 * AC-2: Validates required sections present (not empty, not placeholder)
 * AC-3: Checks UNCERTAIN: and INSUFFICIENT_DATA: items
 * AC-4: Validates guardrail compliance
 * AC-5: Runs Handoff Checklist verification
 * AC-6: Returns APPROVED / FAILED + list of violations
 * AC-8: Extracts QUESTIONNAIRE_REQUEST items
 *
 * @param {object} store - File store
 * @param {object} options
 * @param {string} options.criticState - e.g. 'CRITIC_1'
 * @param {string[]} options.deliverables - Paths to deliverable files
 * @param {string} [options.contractsDir] - Override contracts directory
 * @param {string} [options.guardrailsDir] - Override guardrails directory
 * @returns {{verdict: string, violations: Array, questionnaireRequests: Array, summary: object}}
 */
function runGate(store: any, options: any) {
  const {
    criticState,
    deliverables = [],
    contractsDir = CONTRACTS_DIR,
    guardrailsDir = GUARDRAILS_DIR,
    criticToPhase: ctpOverride,
    phaseContracts: pcOverride,
    phaseGuardrails: pgOverride,
  } = options;

  const ctp = ctpOverride || CRITIC_TO_PHASE;
  const pc = pcOverride || PHASE_CONTRACTS;
  const pg = pgOverride || PHASE_GUARDRAILS;

  const phase = ctp[criticState];
  if (!phase) {
    return {
      verdict: 'FAILED',
      violations: [
        {
          severity: 'CRITICAL',
          rule: 'INVALID_CRITIC_STATE',
          description: `Unknown critic state: ${criticState}`,
        },
      ],
      questionnaireRequests: [],
      summary: { phase: null, deliverableCount: 0, totalViolations: 1 },
    };
  }

  // AC-1: Load contract required sections
  const contractFiles = (pc[phase] || []).map((c) => path.join(contractsDir, c));
  const allRequiredSections = [];
  for (const cp of contractFiles) {
    allRequiredSections.push(...loadContractSections(store, cp));
  }

  // AC-4: Load guardrail rules
  const guardrailFiles = (pg[phase] || []).map((g) => path.join(guardrailsDir, g));
  const allRules = [];
  for (const gp of guardrailFiles) {
    allRules.push(...loadGuardrailRules(store, gp));
  }

  // Validate each deliverable
  const allViolations = [];
  const allQuestionnaireRequests = [];
  const perDeliverable = [];

  if (deliverables.length === 0) {
    allViolations.push({
      severity: 'CRITICAL',
      rule: 'NO_DELIVERABLES',
      description: 'No deliverables provided for gate validation',
    });
  }

  for (const dp of deliverables) {
    if (!store.exists(dp)) {
      const violation = {
        severity: 'CRITICAL',
        rule: 'MISSING_DELIVERABLE',
        description: `Deliverable file not found: ${dp}`,
        deliverable: dp,
      };
      allViolations.push(violation);
      perDeliverable.push({ path: dp, verdict: 'FAILED', violations: [violation] });
      continue;
    }

    const content = store.readFile(dp);
    const result = validateDocument(content, { requiredSections: allRequiredSections });

    // Tag violations with their source deliverable
    const tagged = result.violations.map((v) => ({ ...v, deliverable: dp }));
    allViolations.push(...tagged);

    // AC-8: Collect QUESTIONNAIRE_REQUEST items
    const qr = (result.tags['QUESTIONNAIRE_REQUEST'] || []).map((item) => ({
      ...item,
      deliverable: dp,
    }));
    allQuestionnaireRequests.push(...qr);

    // Also collect INSUFFICIENT_DATA items as questionnaire candidates
    const id = (result.tags['INSUFFICIENT_DATA:'] || []).map((item) => ({
      ...item,
      deliverable: dp,
    }));
    allQuestionnaireRequests.push(...id);

    const hasCrit = result.violations.some((v) => v.severity === 'CRITICAL');
    const delVerdict = hasCrit ? 'FAILED' : 'APPROVED';
    perDeliverable.push({
      path: dp,
      verdict: delVerdict,
      violations: result.violations,
      handoff: result.handoff,
    });
  }

  // AC-6: Determine overall verdict
  const hasCritical = allViolations.some((v) => v.severity === 'CRITICAL');
  const verdict = hasCritical ? 'FAILED' : 'APPROVED';

  const summary = {
    phase,
    criticState,
    deliverableCount: deliverables.length,
    totalViolations: allViolations.length,
    bySeverity: {
      CRITICAL: allViolations.filter((v) => v.severity === 'CRITICAL').length,
      MAJOR: allViolations.filter((v) => v.severity === 'MAJOR').length,
      MINOR: allViolations.filter((v) => v.severity === 'MINOR').length,
      INFO: allViolations.filter((v) => v.severity === 'INFO').length,
    },
    guardrailRulesLoaded: allRules.length,
    contractSectionsLoaded: allRequiredSections.length,
    questionnaireRequestCount: allQuestionnaireRequests.length,
    perDeliverable,
    timestamp: new Date().toISOString(),
  };

  return {
    verdict,
    violations: allViolations,
    questionnaireRequests: allQuestionnaireRequests,
    summary,
  };
}

// ΓöÇΓöÇΓöÇ Class Wrappers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * CriticValidator ΓÇö validates deliverables against contracts & handoff checklist.
 * Wraps runGate with critic-specific defaults.
 */
class CriticValidator {
  _store: any;
  _contractsDir: string;
  _guardrailsDir: string;
  _criticToPhase: any;
  _phaseContracts: any;
  _phaseGuardrails: any;

  /**
   * @param {object} store - File store
   * @param {object} [options] - { contractsDir, guardrailsDir }
   */
  constructor(store: any, options: any = {}) {
    if (!store) throw new Error('CriticValidator requires a store');
    this._store = store;
    this._contractsDir = options.contractsDir || CONTRACTS_DIR;
    this._guardrailsDir = options.guardrailsDir || GUARDRAILS_DIR;
    this._criticToPhase = options.criticToPhase || null;
    this._phaseContracts = options.phaseContracts || null;
    this._phaseGuardrails = options.phaseGuardrails || null;
  }

  /**
   * Validate deliverables for a specific critic gate.
   * @param {string} criticState - e.g. 'CRITIC_1'
   * @param {string[]} deliverables - Paths to deliverable files
   * @returns {{verdict: string, violations: Array, questionnaireRequests: Array, summary: object}}
   */
  validate(criticState: string, deliverables: string[]) {
    return runGate(this._store, {
      criticState,
      deliverables,
      contractsDir: this._contractsDir,
      guardrailsDir: this._guardrailsDir,
      criticToPhase: this._criticToPhase,
      phaseContracts: this._phaseContracts,
      phaseGuardrails: this._phaseGuardrails,
    });
  }
}

/**
 * RiskValidator ΓÇö validates deliverables with focus on risk-related tags.
 * Wraps runGate and extends with risk-specific analysis.
 */
class RiskValidator {
  _store: any;
  _contractsDir: string;
  _guardrailsDir: string;
  _criticToPhase: any;
  _phaseContracts: any;
  _phaseGuardrails: any;

  /**
   * @param {object} store - File store
   * @param {object} [options] - { contractsDir, guardrailsDir }
   */
  constructor(store: any, options: any = {}) {
    if (!store) throw new Error('RiskValidator requires a store');
    this._store = store;
    this._contractsDir = options.contractsDir || CONTRACTS_DIR;
    this._guardrailsDir = options.guardrailsDir || GUARDRAILS_DIR;
    this._criticToPhase = options.criticToPhase || null;
    this._phaseContracts = options.phaseContracts || null;
    this._phaseGuardrails = options.phaseGuardrails || null;
  }

  /**
   * Validate deliverables for risk assessment.
   * @param {string} criticState - e.g. 'CRITIC_1'
   * @param {string[]} deliverables - Paths to deliverable files
   * @returns {{verdict: string, violations: Array, risks: Array, summary: object}}
   */
  validate(criticState: string, deliverables: string[]) {
    const result = runGate(this._store, {
      criticState,
      deliverables,
      contractsDir: this._contractsDir,
      guardrailsDir: this._guardrailsDir,
      criticToPhase: this._criticToPhase,
      phaseContracts: this._phaseContracts,
      phaseGuardrails: this._phaseGuardrails,
    });

    // Extract risk-specific items from tags
    const risks = [];
    for (const del of deliverables) {
      if (!this._store.exists(del)) continue;
      const content = this._store.readFile(del);
      const securityFlags = extractTaggedItems(content, 'SECURITY_FLAG:');
      const uncertainItems = extractTaggedItems(content, 'UNCERTAIN:');
      risks.push(
        ...securityFlags.map((s) => ({ ...s, deliverable: del, type: 'security' })),
        ...uncertainItems.map((u) => ({ ...u, deliverable: del, type: 'uncertainty' }))
      );
    }

    return {
      verdict: result.verdict,
      violations: result.violations,
      risks,
      summary: { ...result.summary, riskItemCount: risks.length },
    };
  }
}

export {
  CRITIC_TO_PHASE,
  PHASE_GUARDRAILS,
  PHASE_CONTRACTS,
  PLACEHOLDER_PATTERNS,
  TRACKED_TAGS,
  HANDOFF_CHECKLIST_COUNT,
  extractSections,
  findPlaceholders,
  extractTaggedItems,
  parseHandoffChecklist,
  loadContractSections,
  loadGuardrailRules,
  validateDocument,
  runGate,
  CriticValidator,
  RiskValidator,
};

/**
 * Sprint Gate ΓÇö Definition of Ready & Readiness Checks (FEAT-05-D)
 *
 * Runs before each Phase 5 sprint iteration to validate readiness:
 *   Step 0: Load reevaluate triggers and decisions from decisions.md
 *   Step 1: Definition of Ready ΓÇö stories have ACs, estimates, deps resolved
 *   Step 2: Lessons-learned injection from retrospectives
 *   Step 3: Velocity-based capacity check (planned SP vs trailing average)
 *   Step 4: Blocker check ΓÇö cross-team dependencies
 *
 * Returns: READY / NOT_READY + list of blockers
 *
 * @module orchestrator/sprint-gate
 */

import _path from 'path';
import { findPromotionCandidates } from '../../src/webapp/lesson-promotion';

// ΓöÇΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const DECISIONS_PATH = 'BusinessDocs/decisions.md';
const LESSONS_LEARNED_PATH = 'BusinessDocs/retrospectives/lessons-learned.md';
const VELOCITY_LOG_PATH = 'BusinessDocs/retrospectives/velocity-log.json';
const BLOCKER_MATRIX_PATH = 'BusinessDocs/synthesis/cross-team-blocker-matrix.md';
const REEVALUATE_TRIGGER_PATH = 'BusinessDocs/session/reevaluate-trigger.json';

/** Trailing sprint count for velocity average */
const VELOCITY_WINDOW = 3;

/** Maximum over-commit percentage before flagging capacity risk */
const CAPACITY_THRESHOLD = 1.2;

// ΓöÇΓöÇΓöÇ Step 0: Decisions & Reevaluate Triggers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Parse decisions from decisions.md.
 * Extracts uncategorized decisions table and open questions table.
 * @param {string} content - decisions.md content
 * @returns {{ decided: Array, openQuestions: Array, categories: Array }}
 */
function parseDecisions(content: string) {
  const decided = [];
  const openQuestions = [];
  const categories = [];

  const lines = content.split('\n');

  // Parse open questions table
  let inOpenQuestions = false;
  let inUncategorized = false;
  let inCategories = false;

  for (const line of lines) {
    const trimmed = line.trim();

    // Detect section starts
    if (/^##\s+Open Questions/i.test(trimmed)) {
      inOpenQuestions = true;
      inUncategorized = false;
      inCategories = false;
      continue;
    }
    if (/^###?\s+Uncategorized Decisions/i.test(trimmed)) {
      inUncategorized = true;
      inOpenQuestions = false;
      inCategories = false;
      continue;
    }
    if (/^##\s+Decision Categories/i.test(trimmed)) {
      inCategories = true;
      inOpenQuestions = false;
      inUncategorized = false;
      continue;
    }
    if (/^##\s+/.test(trimmed) && !inOpenQuestions && !inUncategorized && !inCategories) {
      inOpenQuestions = false;
      inUncategorized = false;
      inCategories = false;
    }

    // Parse table rows (skip header/separator)
    if (
      !trimmed.startsWith('|') ||
      /^\|\s*-/.test(trimmed) ||
      /^\|\s*ID\s*\|/.test(trimmed) ||
      /^\|\s*Stack\s*\|/.test(trimmed)
    ) {
      continue;
    }

    const cells = trimmed
      .split('|')
      .map((c) => c.trim())
      .filter(Boolean);
    if (cells.length < 3) continue;

    if (inOpenQuestions) {
      const [id, priority, scope, question, answer, date] = cells;
      if (id && /^[A-Z]/.test(id) && !question?.includes('No open questions')) {
        openQuestions.push({
          id,
          priority,
          scope,
          question,
          answer: answer || '',
          date: date || '',
        });
      }
    } else if (inUncategorized) {
      const [id, priority, scope, decision, notes, date] = cells;
      if (id && /^DEC-/.test(id) && !decision?.includes('Add a decision here')) {
        decided.push({ id, priority, scope, decision, notes: notes || '', date: date || '' });
      }
    } else if (inCategories) {
      const [stack, file, count, status, applicable] = cells;
      if (stack && status) {
        const fileMatch = (file || '').match(/\[(.+?)\]\((.+?)\)/);
        categories.push({
          stack,
          file: fileMatch ? fileMatch[2] : file || '',
          count: parseInt(count, 10) || 0,
          status: status.toUpperCase(),
          applicable: applicable || '',
        });
      }
    }
  }

  return { decided, openQuestions, categories };
}

/**
 * Load reevaluate trigger from session directory.
 * @param {object} store
 * @param {string} [triggerPath]
 * @returns {{ pending: boolean, scope: string|null, reason: string|null }}
 */
function loadReevaluateTrigger(store: any, triggerPath: string) {
  const fp = triggerPath || REEVALUATE_TRIGGER_PATH;
  if (!store.exists(fp)) return { pending: false, scope: null, reason: null };

  try {
    const data = JSON.parse(store.readFile(fp));
    return {
      pending: data.status === 'PENDING',
      scope: data.scope || null,
      reason: data.reason || null,
    };
  } catch {
    return { pending: false, scope: null, reason: null };
  }
}

/**
 * Step 0: Load decisions and reevaluate triggers.
 * Returns blocking HIGH-priority open questions and active decisions.
 * @param {object} store
 * @param {string} sprintScope - e.g. 'SP-5' or 'Phase 5'
 * @param {object} [paths]
 * @param {object} [templateConfig]
 * @param {Array<{file: string, name: string, defaultStatus: string}>} [templateConfig.decisionCategories] - Template-defined categories
 * @returns {{ decisions: Array, blockingQuestions: Array, reevaluate: object, activeCategories: Array }}
 */
function loadDecisionsAndTriggers(
  store: any,
  sprintScope: any,
  paths: any = {},
  templateConfig: any = {}
) {
  const decisionsPath = paths.decisionsPath || DECISIONS_PATH;
  const triggerPath = paths.triggerPath || REEVALUATE_TRIGGER_PATH;

  let decisions = { decided: [], openQuestions: [], categories: [] };
  if (store.exists(decisionsPath)) {
    decisions = parseDecisions(store.readFile(decisionsPath));
  }

  // HIGH-priority open questions whose scope overlaps with this sprint block the gate
  const blockingQuestions = decisions.openQuestions.filter((q) => {
    if (q.priority !== 'HIGH') return false;
    const scope = (q.scope || '').toLowerCase();
    const sprintLower = sprintScope.toLowerCase();
    return scope.includes('all') || scope.includes('phase 5') || scope.includes(sprintLower);
  });

  const reevaluate = loadReevaluateTrigger(store, triggerPath);

  // Merge template-defined categories with parsed categories from the markdown.
  // Template categories provide the authoritative defaultStatus when present.
  let activeCategories;
  if (
    templateConfig.decisionCategories &&
    Array.isArray(templateConfig.decisionCategories) &&
    templateConfig.decisionCategories.length > 0
  ) {
    activeCategories = templateConfig.decisionCategories.filter(
      (c) => c.defaultStatus === 'ACTIVE'
    );
  } else {
    activeCategories = decisions.categories.filter((c) => c.status === 'ACTIVE');
  }

  return {
    decisions: decisions.decided,
    blockingQuestions,
    reevaluate,
    activeCategories,
  };
}

// ΓöÇΓöÇΓöÇ Step 1: Definition of Ready ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Validate that all sprint stories meet the Definition of Ready.
 * Each story must have: title, acceptance criteria, estimate, dependencies resolved.
 *
 * @param {Array<object>} stories - Sprint backlog items
 * @returns {{ ready: boolean, issues: Array }}
 */
function checkDefinitionOfReady(stories: any[]) {
  const issues = [];

  if (!stories || stories.length === 0) {
    issues.push({
      severity: 'CRITICAL',
      rule: 'NO_STORIES',
      description: 'Sprint backlog is empty ΓÇö no stories to execute',
    });
    return { ready: false, issues };
  }

  for (const story of stories) {
    const id = story.id || story.title || '(unknown)';

    if (!story.title || !story.title.trim()) {
      issues.push({
        severity: 'CRITICAL',
        rule: 'MISSING_TITLE',
        description: `Story "${id}" has no title`,
        storyId: id,
      });
    }

    if (!story.acceptanceCriteria || story.acceptanceCriteria.length === 0) {
      issues.push({
        severity: 'CRITICAL',
        rule: 'MISSING_AC',
        description: `Story "${id}" has no acceptance criteria`,
        storyId: id,
      });
    }

    if (story.estimate == null || story.estimate <= 0) {
      issues.push({
        severity: 'MAJOR',
        rule: 'MISSING_ESTIMATE',
        description: `Story "${id}" has no estimate or estimate is zero`,
        storyId: id,
      });
    }

    if (story.dependencies && story.dependencies.length > 0) {
      const unresolved = story.dependencies.filter((d) => d.status !== 'RESOLVED');
      for (const dep of unresolved) {
        issues.push({
          severity: 'CRITICAL',
          rule: 'UNRESOLVED_DEPENDENCY',
          description: `Story "${id}" has unresolved dependency: ${dep.id || dep.description || 'unknown'}`,
          storyId: id,
          dependency: dep,
        });
      }
    }
  }

  const hasCritical = issues.some((i) => i.severity === 'CRITICAL');
  return { ready: !hasCritical, issues };
}

// ΓöÇΓöÇΓöÇ Step 2: Lessons-Learned Injection ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Parse lessons from lessons-learned.md.
 * Extracts "Top N Lessons for Sprint X Injection" section if present,
 * otherwise returns all lessons from the latest sprint section.
 *
 * @param {string} content - lessons-learned.md content
 * @returns {Array<{id: string, lesson: string, type: string, appliesTo: string}>}
 */
function parseLessonsLearned(content: string) {
  const lessons = [];
  const lines = content.split('\n');

  // First try: find "Top N Lessons" injection section
  let inInjection = false;
  for (const line of lines) {
    if (/^##\s+Top\s+\d+\s+Lessons/i.test(line)) {
      inInjection = true;
      continue;
    }
    if (inInjection) {
      if (/^---/.test(line.trim()) || /^##\s+/.test(line)) break;
      const numbered = line.match(/^\d+\.\s+\*\*(\w+)\s*[ΓÇöΓÇô-]\s*(.+?)\*\*/);
      if (numbered) {
        lessons.push({
          id: numbered[1],
          lesson: numbered[2].trim(),
          type: 'injection',
          appliesTo: 'current-sprint',
        });
      }
    }
  }
  if (lessons.length > 0) return lessons;

  // Fallback: parse latest sprint table rows
  let latestSectionStart = -1;
  for (let i = lines.length - 1; i >= 0; i--) {
    if (/^##\s+Sprint\s+\d+\s+Lessons/i.test(lines[i])) {
      latestSectionStart = i;
      break;
    }
  }

  if (latestSectionStart >= 0) {
    for (let i = latestSectionStart + 1; i < lines.length; i++) {
      if (/^##\s+/.test(lines[i]) || /^---/.test(lines[i].trim())) break;
      const row = lines[i].trim();
      if (!row.startsWith('|') || /^\|\s*-/.test(row) || /^\|\s*ID\s*\|/.test(row)) continue;
      const cells = row
        .split('|')
        .map((c) => c.trim())
        .filter(Boolean);
      if (cells.length >= 4 && /^L\d+/.test(cells[0])) {
        lessons.push({
          id: cells[0],
          lesson: cells[1],
          type: cells[2],
          appliesTo: cells[3],
        });
      }
    }
  }

  return lessons;
}

/**
 * Step 2: Load and inject lessons learned.
 * Also detects lessons flagged with PROMOTE_TO_DECISION.
 * @param {object} store
 * @param {string} [lessonsPath]
 * @returns {{ lessons: Array, count: number, promotionCandidates: Array }}
 */
function loadLessonsLearned(store: any, lessonsPath: string): any {
  const fp = lessonsPath || LESSONS_LEARNED_PATH;
  if (!store.exists(fp)) return { lessons: [], count: 0, promotionCandidates: [] };

  const content = store.readFile(fp);
  const lessons = parseLessonsLearned(content);
  const promotionCandidates = findPromotionCandidates(content);
  return { lessons, count: lessons.length, promotionCandidates };
}

// ΓöÇΓöÇΓöÇ Step 3: Velocity-Based Capacity Check ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Parse the velocity log JSON and compute trailing average.
 * @param {string} jsonContent - velocity-log.json content
 * @param {number} [window] - Number of past sprints to average
 * @returns {{ sprints: Array, trailingAverage: number, sprintCount: number }}
 */
function parseVelocityLog(jsonContent: string, window: number) {
  const w = window || VELOCITY_WINDOW;

  let data;
  try {
    data = JSON.parse(jsonContent);
  } catch {
    return { sprints: [], trailingAverage: 0, sprintCount: 0 };
  }

  const sprints = data.sprints || [];
  if (sprints.length === 0) return { sprints: [], trailingAverage: 0, sprintCount: 0 };

  // Use the last `w` sprints for trailing average
  const recent = sprints.slice(-w);
  const totalCompleted = recent.reduce((sum, s) => sum + (s.completed_items || 0), 0);
  const trailingAverage = recent.length > 0 ? totalCompleted / recent.length : 0;

  return { sprints, trailingAverage, sprintCount: recent.length };
}

/**
 * Step 3: Check if planned items fit within velocity capacity.
 * @param {object} store
 * @param {number} plannedItems - Number of items planned for next sprint
 * @param {object} [opts]
 * @returns {{ withinCapacity: boolean, plannedItems: number, trailingAverage: number, ratio: number, issues: Array }}
 */
function checkVelocityCapacity(store: any, plannedItems: number, opts: any = {}) {
  const velocityPath = opts.velocityPath || VELOCITY_LOG_PATH;
  const threshold = opts.capacityThreshold || CAPACITY_THRESHOLD;
  const issues = [];

  if (!store.exists(velocityPath)) {
    return {
      withinCapacity: true,
      plannedItems,
      trailingAverage: 0,
      ratio: 0,
      issues: [
        {
          severity: 'INFO',
          rule: 'NO_VELOCITY_DATA',
          description: 'No velocity history available ΓÇö skipping capacity check',
        },
      ],
    };
  }

  const content = store.readFile(velocityPath);
  const { trailingAverage, sprintCount } = parseVelocityLog(content, opts.window);

  if (sprintCount === 0 || trailingAverage === 0) {
    return {
      withinCapacity: true,
      plannedItems,
      trailingAverage: 0,
      ratio: 0,
      issues: [
        {
          severity: 'INFO',
          rule: 'INSUFFICIENT_VELOCITY_DATA',
          description: 'Not enough velocity data for capacity check',
        },
      ],
    };
  }

  const ratio = plannedItems / trailingAverage;

  if (ratio > threshold) {
    issues.push({
      severity: 'MAJOR',
      rule: 'OVER_CAPACITY',
      description: `Planned ${plannedItems} items but trailing average is ${trailingAverage.toFixed(1)} (ratio: ${ratio.toFixed(2)}, threshold: ${threshold})`,
      plannedItems,
      trailingAverage,
      ratio,
    });
  }

  return {
    withinCapacity: ratio <= threshold,
    plannedItems,
    trailingAverage,
    ratio,
    issues,
  };
}

// ΓöÇΓöÇΓöÇ Step 4: Blocker Check ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Parse the cross-team blocker matrix markdown.
 * @param {string} content
 * @returns {Array<{id: string, sourceTarget: string, description: string, classification: string, status: string}>}
 */
function parseBlockerMatrix(content: string) {
  const blockers = [];
  const lines = content.split('\n');
  let inTable = false;

  for (const line of lines) {
    const trimmed = line.trim();
    if (/^\|\s*Blocker ID/i.test(trimmed)) {
      inTable = true;
      continue;
    }
    if (inTable && /^\|\s*-/.test(trimmed)) continue;
    if (inTable && !trimmed.startsWith('|')) {
      inTable = false;
      continue;
    }
    if (!inTable) continue;

    const cells = trimmed
      .split('|')
      .map((c) => c.trim())
      .filter(Boolean);
    if (cells.length >= 5) {
      blockers.push({
        id: cells[0],
        sourceTarget: cells[1],
        description: cells[2],
        classification: cells[3].toUpperCase(),
        status: cells[4].toUpperCase(),
      });
    }
  }

  return blockers;
}

/**
 * Step 4: Check for open BLOCKING cross-team dependencies.
 * @param {object} store
 * @param {string} [blockerPath]
 * @returns {{ clear: boolean, openBlockers: Array, advisories: Array, issues: Array }}
 */
function checkBlockers(store: any, blockerPath: string) {
  const fp = blockerPath || BLOCKER_MATRIX_PATH;
  const issues = [];

  if (!store.exists(fp)) {
    return {
      clear: true,
      openBlockers: [],
      advisories: [],
      issues: [
        {
          severity: 'INFO',
          rule: 'NO_BLOCKER_MATRIX',
          description: 'Cross-team blocker matrix not found ΓÇö skipping blocker check',
        },
      ],
    };
  }

  const content = store.readFile(fp);
  const allBlockers = parseBlockerMatrix(content);

  const openBlockers = allBlockers.filter(
    (b) => b.classification === 'BLOCKING' && b.status === 'OPEN'
  );
  const advisories = allBlockers.filter(
    (b) => b.classification === 'ADVISORY' && b.status === 'OPEN'
  );

  for (const blocker of openBlockers) {
    issues.push({
      severity: 'CRITICAL',
      rule: 'OPEN_BLOCKER',
      description: `Open blocker ${blocker.id}: ${blocker.sourceTarget} ΓÇö ${blocker.description}`,
      blockerId: blocker.id,
    });
  }

  for (const adv of advisories) {
    issues.push({
      severity: 'INFO',
      rule: 'OPEN_ADVISORY',
      description: `Advisory ${adv.id}: ${adv.sourceTarget} ΓÇö ${adv.description}`,
      blockerId: adv.id,
    });
  }

  return {
    clear: openBlockers.length === 0,
    openBlockers,
    advisories,
    issues,
  };
}

// ΓöÇΓöÇΓöÇ Sprint Gate Runner ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Run the full Sprint Gate readiness check.
 *
 * @param {object} store - File store
 * @param {object} options
 * @param {string} options.sprintId - e.g. 'SP-5'
 * @param {Array<object>} options.stories - Sprint backlog items
 * @param {number} [options.plannedItems] - Override planned item count
 * @param {object} [options.paths] - Override file paths
 * @returns {{verdict: string, blockers: Array, steps: object, summary: object}}
 */
function runSprintGate(store: any, options: any): any {
  const { sprintId, stories = [], plannedItems, paths = {}, templateConfig = {} } = options;

  if (!sprintId) {
    return {
      verdict: 'NOT_READY',
      blockers: [
        {
          severity: 'CRITICAL',
          rule: 'NO_SPRINT_ID',
          description: 'Sprint ID is required for Sprint Gate',
        },
      ],
      steps: {},
      summary: { sprintId: null, timestamp: new Date().toISOString() },
    };
  }

  // Step 0: Decisions & reevaluate triggers
  const step0 = loadDecisionsAndTriggers(store, sprintId, paths, templateConfig);

  // Step 1: Definition of Ready
  const step1 = checkDefinitionOfReady(stories);

  // Step 2: Lessons-learned injection
  const step2 = loadLessonsLearned(store, paths.lessonsPath);

  // Step 3: Velocity capacity check
  const itemCount = plannedItems != null ? plannedItems : stories.length;
  const step3 = checkVelocityCapacity(store, itemCount, paths);

  // Step 4: Blocker check
  const step4 = checkBlockers(store, paths.blockerPath);

  // Collect all blocking issues
  const allBlockers = [];

  // Step 0 blockers: HIGH-priority open questions and pending reevaluate
  for (const q of step0.blockingQuestions) {
    allBlockers.push({
      severity: 'CRITICAL',
      rule: 'BLOCKING_QUESTION',
      description: `HIGH-priority open question ${q.id}: ${q.question}`,
      questionId: q.id,
    });
  }
  if (step0.reevaluate.pending) {
    allBlockers.push({
      severity: 'CRITICAL',
      rule: 'REEVALUATE_PENDING',
      description: `Reevaluation pending: ${step0.reevaluate.reason || 'no reason given'} (scope: ${step0.reevaluate.scope || 'unknown'})`,
    });
  }

  // Step 1 blockers
  allBlockers.push(...step1.issues.filter((i) => i.severity === 'CRITICAL'));

  // Step 3 blockers (over-capacity is MAJOR, not auto-blocking but tracked)
  allBlockers.push(...step3.issues.filter((i) => i.severity === 'CRITICAL'));

  // Step 4 blockers
  allBlockers.push(...step4.issues.filter((i) => i.severity === 'CRITICAL'));

  const verdict = allBlockers.length === 0 ? 'READY' : 'NOT_READY';

  const steps = {
    step0_decisions: {
      decisions: step0.decisions,
      blockingQuestions: step0.blockingQuestions,
      reevaluate: step0.reevaluate,
      activeCategories: step0.activeCategories,
    },
    step1_definitionOfReady: {
      ready: step1.ready,
      issues: step1.issues,
      storyCount: stories.length,
    },
    step2_lessonsLearned: {
      lessons: step2.lessons,
      count: step2.count,
      promotionCandidates: step2.promotionCandidates,
    },
    step3_velocityCapacity: {
      withinCapacity: step3.withinCapacity,
      plannedItems: step3.plannedItems,
      trailingAverage: step3.trailingAverage,
      ratio: step3.ratio,
      issues: step3.issues,
    },
    step4_blockerCheck: {
      clear: step4.clear,
      openBlockers: step4.openBlockers,
      advisories: step4.advisories,
      issues: step4.issues,
    },
  };

  const summary = {
    sprintId,
    verdict,
    totalBlockers: allBlockers.length,
    storyCount: stories.length,
    lessonsInjected: step2.count,
    promotionCandidates: step2.promotionCandidates.length,
    velocityRatio: step3.ratio,
    openBlockerCount: step4.openBlockers.length,
    advisoryCount: step4.advisories.length,
    decisionsLoaded: step0.decisions.length,
    activeCategoryCount: step0.activeCategories.length,
    timestamp: new Date().toISOString(),
  };

  return { verdict, blockers: allBlockers, steps, summary };
}

