// ΓöÇΓöÇΓöÇ Schema Validation ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Required top-level keys in a valid manifest.
 * Used for lightweight validation when JSON Schema (ajv) is not available.
 */
const REQUIRED_MANIFEST_KEYS = [
  'schemaVersion',
  'name',
  'version',
  'description',
