  // eslint-disable-next-line complexity
  async () => {
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const { detectDrift } = require('./drift-detector') as {
        detectDrift: (opts: {
          sessionState: SessionState;
