 */

import { getStore } from '../store';
import { json } from '../middleware';

/* ΓöÇΓöÇ Agent / phase constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */

const PHASE_AGENTS = {
  ONBOARDING: [{ id: '25', name: 'Onboarding Agent' }],
  'PHASE-1': [
